		else if(player[i].joining && player[i].name[0])
		{
			model = findmodel(player[i].name);
			font_printf(videomodes.shiftpos[i]+pnameJ[i][0], savedata.windowpos+pnameJ[i][1], pnameJ[i][6], 0, player[i].name);
