                    }
                }
                // NOSAME X 2
                player[i].playkeys = 0;
            }
        }
        else if( !nojoin && (player[i].credits || credits || (!player[i].hasplayed && noshare)) )
        {
            if(player[i].playkeys & FLAG_START)
            {
                player[i].lives = 0;
                model = skipselect[i][0] ? findmodel(skipselect[i]) : nextplayermodeln(NULL, i);
                strncpy(player[i].name, model->name, MAX_NAME_LEN);

                //player[i].colourmap = (colourselect && (set->nosame & 2)) ? nextcolourmap(model, i - 1) : 0;
                // NOSAME X 2 // By White Dragon
                player[i].colourmap = 0;
                if ( colourselect && (set->nosame & 2) )
                {
                    int nosamef = -1;
                    int ii = 0;
                    for(ii = 0; ii < set->maxplayers; ii++)
                    {
                        if ( i != ii && stricmp(player[i].name,player[ii].name) == 0 )
                        {
                            if ( player[i].colourmap == player[ii].colourmap  )
                            {
                                if ( nosamef == player[ii].colourmap ) break; // avoid infinite loop
                                player[i].colourmap = nextcolourmap(model,player[i].colourmap);
                                ii = 0;
                                if ( nosamef == -1 ) nosamef = player[ii].colourmap;
                                continue;
                            }
                        } else continue;
                    }
                }
                // NOSAME X 2

                player[i].joining = 1;
                player[i].disablekeys = player[i].playkeys = player[i].newkeys = player[i].releasekeys = 0;

                if(!level->noreset)
                {
                    timeleft = level->settime * COUNTER_SPEED;    // Feb 24, 2005 - This line moved here to set custom time
                }

                if(!player[i].hasplayed && noshare)
                {
                    player[i].credits = CONTINUES;
                }

                if(!creditscheat)
                {
                    if(noshare)
                    {
                        --player[i].credits;
                    }
                    else
                    {
                        --credits;
                    }
                    if(set->continuescore == 1)
                    {
                        player[i].score = 0;
                    }
                    if(set->continuescore == 2)
                    {
                        player[i].score = player[i].score + 1;
                    }
                }
            }
        }
    }// end of for

    dt = timeleft / COUNTER_SPEED;
    if(dt >= 99)
    {
        dt      = 99;

        oldtime = 99;
    }
    if(dt <= 0)
    {
        dt      = 0;
        oldtime = 99;
    }

    if(dt < oldtime || oldtime == 0)
    {
        execute_timetick_script(dt, go_time);
        oldtime = dt;
    }

    timetoshow = dt;

    if(dt < 99)
    {
        showtimeover = 0;
    }

    if(go_time > time)
    {
        dt = (go_time - time) % GAME_SPEED;

        if(dt < GAME_SPEED / 2)
        {
            showgo = 1;
            if(gosound == 0 )
            {

                if(SAMPLE_GO >= 0)
                {
                    sound_play_sample(SAMPLE_GO, 0, savedata.effectvol, savedata.effectvol, 100);    // 26-12-2004 Play go sample as arrow flashes
                }

                gosound = 1;                // 26-12-2004 Sets sample as already played - stops sample repeating too much
            }
        }
        else
        {
            showgo = gosound = 0;    //26-12-2004 Resets go sample after loop so it can be played again next time
        }
    }
    else
    {
        showgo = 0;
    }

}

4432.predrawstatus:
void predrawstatus()
